14: // Release an IUnknown* and set to nullptr.
15: // While IUnknown::Release must be noexcept, it isn't marked as such so produces
16: // warnings which are avoided by the catch.
17: template <class T>
18: inline void ReleaseUnknown(T *&ppUnknown) noexcept {
19: 	if (ppUnknown) {
20: 		try {
21: 			ppUnknown->Release();
22: 		} catch (...) {
23: 			// Never occurs
24: 		}
25: 		ppUnknown = nullptr;
26: 	}
27: }
28: 
29: struct UnknownReleaser {
30: 	// Called by unique_ptr to destroy/free the resource
31: 	template <class T>
32: 	void operator()(T *pUnknown) noexcept {
33: 		try {
34: 			pUnknown->Release();
35: 		} catch (...) {
36: 			// IUnknown::Release must not throw, ignore if it does.
37: 		}
38: 	}
39: };
40: 
41: 
42: /// Find a function in a DLL and convert to a function pointer.
43: /// This avoids undefined and conditionally defined behaviour.
44: template<typename T>
45: inline T DLLFunction(HMODULE hModule, LPCSTR lpProcName) noexcept {
46: 	if (!hModule) {
47: 		return nullptr;
48: 	}
49: 	FARPROC function = ::GetProcAddress(hModule, lpProcName);
50: 	static_assert(sizeof(T) == sizeof(function));
51: 	T fp {};
52: 	memcpy(&fp, &function, sizeof(T));
53: 	return fp;
54: }
55: 
56: }
